package es.riegocerca.maps; import android.app.Activity; import android.content.Intent; import android.net.Uri; import android.webkit.JavascriptInterface; import org.json.JSONArray;
public class MapsBridge{private final Activity a;MapsBridge(Activity a){this.a=a;}@JavascriptInterface public void navigate(double lat,double lon){open("https://www.google.com/maps/dir/?api=1&destination="+lat+","+lon+"&travelmode=driving");}@JavascriptInterface public void openMulti(String j){try{JSONArray p=new JSONArray(j);if(p.length()==0)return;String d=p.getString(p.length()-1);StringBuilder u=new StringBuilder("https://www.google.com/maps/dir/?api=1&destination=").append(Uri.encode(d)).append("&travelmode=driving");if(p.length()>1){u.append("&waypoints=");for(int i=0;i<p.length()-1;i++){if(i>0)u.append("%7C");u.append(Uri.encode(p.getString(i)));}}open(u.toString());}catch(Exception e){}}@JavascriptInterface public void earth(double lat,double lon){open("https://earth.google.com/web/search/"+lat+","+lon);}@JavascriptInterface public void whatsapp(String text){open("https://wa.me/34615179537?text="+Uri.encode(text));}private void open(String u){a.runOnUiThread(()->{try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception e){}});}}
